  ('beauty_wellness', 'Beauty & Wellness', ARRAY['Marketplace', 'Booking & Appointments', 'E-commerce', 'Social & Community', 'Dashboard SaaS', 'Content & Streaming', 'Chat / Messaging', 'Map & Location-Based', 'AI Tool', 'Developer Tool'], '{"industry_id":"beauty_wellness","industry_name":"Beauty & Wellness","tone":{"primary":"warm, indulgent, aspirational","secondary":"trustworthy, personal, empowering","voice":"friendly and expert — like a knowledgeable friend who happens to be a beauty professional","avoid":"clinical, cold, overly technical, masculine-coded language"},"trust_signals":["star ratings and review count","before/after results","certified professional badges","real customer photos","booking confirmation and reminders","secure payment indicators","cancellation policy visibility"],"ux_norms":["image-first layouts — large beautiful visuals dominate","soft rounded corners throughout","feminine-leaning but inclusive visual language","calendar and time pickers are central UI elements","wishlist and save functionality expected","loyalty points and rewards commonly shown","before/after sliders for product results","horizontal scroll for categories and products"],"icons":{"style":"soft duotone or rounded line","weight":"light to medium","mood":"elegant, warm, approachable","library":{"name":"Phosphor Icons","variant":"Duotone","url":"https://phosphoricons.com"},"domain_icons":["flower","sparkle","drop","hand-soap","scissors","heart","star","leaf","sun","bottle","eye","palette"],"nav_icons":["house","magnifying-glass","bag","heart","user","bell","funnel","grid-four","arrow-left","dots-three"]},"visual_language":{"primary_type":"real photography","style":"soft, warm, high-key lighting — lifestyle and product focused","photography_rules":["always show real people and real results","warm skin tones, natural lighting preferred","product closeups with soft shadows","never use cold or harsh lighting","diverse representation expected"],"background_treatment":"soft war