ol":{"headline":"Prompt. Generate. Ship.","cta":"Start building"},"Developer Tool":{"headline":"The tool your stack was missing","cta":"Get started free"},"Dashboard SaaS":{"headline":"Every project, every build, one view","cta":"Open dashboard"},"default":{"headline":"Built for developers, by developers","cta":"Get started"}}}'::jsonb, 3),
  ('education', 'Education', ARRAY['Marketplace', 'Booking & Appointments', 'E-commerce', 'Social & Community', 'Dashboard SaaS', 'Content & Streaming', 'Chat / Messaging', 'Map & Location-Based', 'AI Tool', 'Developer Tool', 'LMS / Course Builder'], '{"industry_id":"education","industry_name":"Education","tone":{"primary":"encouraging, clear, motivating","secondary":"intelligent, accessible, warm","voice":"a brilliant teacher who believes in you — supportive, never condescending","avoid":"boring, overly academic, intimidating, patronising"},"trust_signals":["instructor credentials and bio","student count and completion rates","course rating and reviews","certificate on completion","accreditation badges where applicable","free preview or trial lesson","money-back guarantee visibility"],"ux_norms":["progress tracking is always visible — completion percentage on every course, module, and assignment","streaks and achievements drive engagement — streak count and milestone badges always on home screen","video player is a primary UI component — custom controls, playback speed, quality selector always accessible","resume where you left off — always — last position in video, last completed lesson highlighted","course outline always accessible — slide-in panel or persistent sidebar depending on platform","lms course builder screens: instructor home leads with pending grades and active course stats — never student-facing content","lms course builder screens: course builder uses drag-to-reorder modules — handle always visible on module row left edge","lms course builder screens: lesson editor uses block-based content — add, remove, reorder blocks — never a single textarea","lms course builder screens: gradebook is a data table — student rows, assignment columns — always exportable","lms course builder screens: grading screen shows submission and grade input side by side — never navigate away to grade","lms course builder screens: student detail shows progress by module, not just overall percentage — granular view always","lms course builder screens: announcements composer always shows recipient count before sending — never send blind","lms course builder screens: discussion threads show unanswered questions with red dot — instructor response urgency always visible","offline access indicators for downloaded content — always visible — critical for mobile learners"],"icons":{"style":"friendly rounded, approachable","weight":"light to medium","mood":"friendly, inspiring, approachable","library":{"name":"Phosphor Icons","variant":"Rounded","url":"https://phosphoricons.com"},"domain_icons":["book","graduation-cap","pencil","certificate","star","play","clock","users","trophy","lightbulb","globe","brain"],"nav_icons":["house","magnifying-glass","play","bookmark","user","bell","list","chart-bar","arrow-left","check"]},"visual_language":{"primary_type":"vector illustrations","style":"friendly, diverse, encouraging — Duolingo-adjacent energy","photography_rules":["real instructor photos for course cards — professional but approachable","diverse student representation in all human imagery","never use stuffy or traditional academic photography"],"background_treatment":"clean white or very light — let colour accents carry the energy","empty_state_style":"friendly illustrated character or object — encouraging copy (you''ve got this!)","onboarding_visual":"friendly flat vector illustration — learning journey theme","illustration_style":"flat vector, rounded shapes, diverse characters — warm and motivating"},"themes":{"pack":["Campus","Scholar","Kids","Focus","Academy"]},"fonts":{"ai_pick_heading":"Nunito","ai_pick_body":"Nunito"},"valid_app_types":["Marketplace","Booking & Appointments","E-commerce","Social & Community","Dashboard SaaS","Content & Streaming","Chat / Messaging","Map & Location-Based","AI Tool","Developer Tool","LMS / Course Builder"],"monetization_models":["per course purchase","monthly or annual subscription","freemium with premium courses","SaaS per seat for institutions","certificate fees","corporate training packages"],"compliance_notes":["COPPA compliance for apps targeting under-13","FERPA for student data in US","accessibility standards (WCAG) especially important","accreditation claims must be verifiable","GDPR for learner data"],"constraints":{"avoid":["Never use gamification that trivialises learning — streaks and points must be secondary to content","Never show a student''s grade to other students — isolation absolute","Never auto-advance through content without completion signal","Never use a countdown timer that creates anxiety during assessments without warning","Never truncate assignment instructions — full text always required","Never use aggressive upgrade prompts during active learning sessions"],"enforce":["Progress always shown as lessons completed / total — never hidden","Deadline always shown in student''s local timezone","Accessibility: all video content must have captions available","Content always saveable for offline access in paid tier","Academic integrity notice always visible on assessment screens","Student support contact always one tap away from any assessment screen"]},"copy_by_app_type":{"AI Tool":{"headline":"Your AI tutor, ready when you are","cta":"Start learning"},"Content & Streaming":{"headline":"Learn anything. At your pace.","cta":"Browse courses"},"Dashboard SaaS":{"headline":"Every student, in focus","cta":"View dashboard"},"LMS / Course Builder":{"headline":"Build your first course today","cta":"Create course"},"Marketplace":{"headline":"Courses from the world''s best teachers","cta":"Explore"},"Social & Community":{"headline":"Learn better, together","cta":"Join the community"},"default":{"headline":"Knowledge, built for you","cta":"Get started"}}}'::jsonb, 4),
