  ('events_ticketing', 'Events & Ticketing', ARRAY['Marketplace', 'Booking & Appointments', 'E-commerce', 'Social & Community', 'Dashboard SaaS', 'Content & Streaming', 'Chat / Messaging', 'Map & Location-Based', 'AI Tool', 'Developer Tool'], '{"industry_id":"events_ticketing","industry_name":"Events & Ticketing","tone":{"primary":"exciting, urgent, experiential","secondary":"trustworthy, clear, energetic","voice":"a friend who got you the best tickets — enthusiastic, in the know, reliable","avoid":"boring, slow, overly corporate, confusing"},"trust_signals":["official event partner or verified organiser badge","secure payment and refund policy visibility","ticket authenticity guarantee","real-time availability indicators","event capacity and sold out signals","QR code ticket delivery","organiser rating and history"],"ux_norms":["urgency is a design element — sold out, limited spots, countdown timers","event imagery is large and immersive","seat map or venue layout for ticketed events","add to calendar is always a post-purchase action","QR code ticket always accessible in wallet","group booking and split payment expected","discovery by date, category, and location","share event is a primary social action"],"icons":{"style":"bold filled, energetic","weight":"bold","mood":"exciting, bold, celebratory","library":{"name":"Phosphor Icons","variant":"Bold filled","url":"https://phosphoricons.com"},"domain_icons":["ticket","confetti","microphone","calendar","map-pin","star","users","music-note","camera","trophy","lightning","flag"],"nav_icons":["house","magnifying-glass","ticket","heart","user","bell","funnel","calendar","arrow-left","dots-three"]},"visual_language":{"primary_type":"real photography and bold graphic vectors","style":"high energy — event photography, dramatic lighting, crowd energy","photography_rules":["event and venue photography drives all decisions","crowd and atmosphere shots for hero sections","performer and artist photography high priority","never use generic stock events imagery"],"background_treatment":"dark and dramatic for premium events — bold colour for festivals and parties","empty_state_style":"bold SVG — ticket, microphone, or stage — with energetic copy","onboarding_visual":"bold graphic vector — stage, crowd, or event silhouette","illustration_style":"bold graphic vector — high contrast, event poster aesthetic"},"themes":{"pack":["Stage","Festival","Corporate Event","Party","Intimate"]},"fonts":{"ai_pick_heading":"Syne","ai_pick_body":"DM Sans"},"valid_app_types":["Marketplace","Booking & Appointments","E-commerce","Social & Community","Dashboard SaaS","Content & Streaming","Chat / Messaging","Map & Location-Based","AI Tool","Developer Tool"],"monetization_models":["ticket booking fee percentage","organiser SaaS subscription","featured event placement","white-label ticketing for venues","add-on sales (merchandise, VIP upgrades)","resale marketplace commission"],"compliance_notes":["consumer protection for refunds and cancellations","GDPR for attendee data","age verification for age-restricted events","accessibility requirements for venues","data retention for ticketing records","anti-touting and anti-scalping measures"],"constraints":{"avoid":["Never hide service fees until the final checkout step — show total cost including fees upfront","Never show ''Only X tickets left'' without it being accurate — fabricated scarcity destroys trust","Never send a ticket without an accessible digital format — QR code minimum","Never require account creation before showing event details","Never auto-renew event access without explicit subscription opt-in","Never use countdown timers on seat selection without holding the seats during that time"],"enforce":["Total price including all fees shown before final confirmation — no surprise fees","Ticket QR code always downloadable and accessible offline","Event capacity and remaining tickets shown accurately","Refund policy always visible on event detail and ticket confirmation","Ticket transfer always available — name change or resale as per platform policy","Event cancellation notification sent immediately via push and email"]},"copy_by_app_type":{"AI Tool":{"headline":"Find your next great event with AI","cta":"Discover events"},"Marketplace":{"headline":"Get tickets to what''s happening","cta":"Browse events"},"Booking & Appointments":{"headline":"Reserve your spot in seconds","cta":"Book now"},"Social & Community":{"headline":"Find your people at every event","cta":"Join now"},"default":{"headline":"Every great event starts here","cta":"Get started"}}}'::jsonb, 6),
  ('finance', 'Finance', ARRAY['Marketplace', 'Booking & Appointments', 'E-commerce', 'Social & Community', 'Dashboard SaaS', 'Content & Streaming', 'Chat / Messaging', 'Map & Location-Based', 'AI Tool', 'Developer Tool', 'Finance Banking'], '{"industry_id":"finance","industry_name":"Finance","tone":{"primary":"serious, trustworthy, precise","secondary":"empowering, clear, secure","voice":"a sharp financial advisor who respects your intelligence — direct, no fluff","avoid":"casual, playful, vague, alarmist, overly complex jargon"},"trust_signals":["security and encryption indicators","regulatory compliance badges (FCA, SEC etc)","two-factor authentication visibility","biometric login support","transaction success confirmations","clear fee transparency","bank-grade security messaging"],"ux_norms":["data density is acceptable — users expect detail","numbers and amounts are always prominent and clear","charts and graphs are primary UI elements","transaction history is always accessible","security confirmation on all sensitive actions","dark mode is common and expected","biometric and PIN auth on every session","clear action confirmation dialogs — no accidental transfers"],"icons":{"style":"sharp line, data-dense, professional","weight":"medium","mood":"authoritative, precise, trustworthy","library":{"name":"Material Symbols","variant":"Sharp","url":"https://fonts.google.com/icons"},"domain_icons":["bar_chart","trending_up","attach_money","verified_user","credit_card","calculate","description","schedule","notifications","lock","account_balance","savings"],"nav_icons":["home","pie_chart","credit_card","description","person","notifications","settings","arrow_back","menu","refresh"]},"visual_language":{"primary_type":"CSS and data visualisation","style":"pure interface — no photography, no illustration on core screens","photography_rules":["no photography on transactional screens","marketing/onboarding only may use abstract lifestyle photography","never use money or cash i