nner"],"monetization_models":["booking commission percentage","host or operator listing fee","travel insurance affiliate","premium placement for listings","subscription for travel perks","experiences and activities marketplace fee"],"compliance_notes":["local tourism licensing requirements vary by region","GDPR for traveller data and preferences","payment regulations for international transactions","cancellation and refund policy must be prominent","accessibility information for destinations required","tax collection requirements vary by jurisdiction"],"constraints":{"avoid":["Never show a destination without photography — imagery is the emotional driver of travel decisions","Never hide visa requirements or entry restrictions for a destination","Never show pricing without specifying the currency","Never use a countdown timer on flight or hotel availability without it being accurate","Never make cancellation terms hard to find — they must be prominent before booking","Never show accommodation without showing the exact address or neighbourhood — location drives decisions"],"enforce":["Destination photography always full bleed — no borders or card containers on hero imagery","Cancellation policy always visible before booking confirmation","Total price including taxes and fees always shown — no hidden costs at checkout","Travel advisory and safety information always available for destination","Local time at destination always shown alongside home timezone","Offline access to booking confirmations and tickets always available"]},"copy_by_app_type":{"AI Tool":{"headline":"Your AI travel planner","cta":"Plan my trip"},"Trip Planner":{"headline":"Your next trip, perfectly planned","cta":"Start planning"},"Marketplace":{"headline":"Find a place that feels like home","cta":"Explore listings"},"Booking & Appointments":{"headline":"Book experiences worth remembering","cta":"Find availability"},"Map & Location-Based":{"headline":"Explore what''s around you","cta":"Open map"},"default":{"headline":"Go further. Live better.","cta":"Get started"}}}'::jsonb, 14);
